<?php
require __DIR__.'/config.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$student=['name'=>'','roll_number'=>'','email'=>'','course'=>''];$error='';
if($id){$q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$id]);$student=$q->fetch();if(!$student){http_response_code(404);exit('Student not found.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;$student=['name'=>trim($_POST['name']??''),'roll_number'=>trim($_POST['roll_number']??''),'email'=>trim($_POST['email']??''),'course'=>trim($_POST['course']??'')];if(in_array('', $student,true)||!filter_var($student['email'],FILTER_VALIDATE_EMAIL)){$error='All fields are required and email must be valid.';}else{try{if($id){$q=$pdo->prepare('UPDATE students SET name=?,roll_number=?,email=?,course=? WHERE id=?');$q->execute([$student['name'],$student['roll_number'],$student['email'],$student['course'],$id]);}else{$q=$pdo->prepare('INSERT INTO students(name,roll_number,email,course) VALUES(?,?,?,?)');$q->execute(array_values($student));$id=(int)$pdo->lastInsertId();}if(isset($_FILES['files'])&&is_array($_FILES['files']['name'])){$allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];$finfo=new finfo(FILEINFO_MIME_TYPE);foreach($_FILES['files']['name'] as $i=>$original){if($_FILES['files']['error'][$i]===UPLOAD_ERR_NO_FILE)continue;if($_FILES['files']['error'][$i]!==UPLOAD_ERR_OK||$_FILES['files']['size'][$i]>5*1024*1024)throw new RuntimeException('Upload failed or file exceeds 5 MB.');$ext=strtolower(pathinfo($original,PATHINFO_EXTENSION));$tmp=$_FILES['files']['tmp_name'][$i];if(!isset($allowed[$ext])||$finfo->file($tmp)!==$allowed[$ext])throw new RuntimeException('Only valid PDF/JPG/PNG files are allowed.');$stored=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($tmp,$uploadDir.$stored))throw new RuntimeException('Could not store uploaded file.');$q=$pdo->prepare('INSERT INTO student_files(student_id,original_name,stored_name,file_path,file_type,file_size) VALUES(?,?,?,?,?,?)');$q->execute([$id,basename($original),$stored,'uploads/'.$stored,$allowed[$ext],(int)$_FILES['files']['size'][$i]]);}}header('Location: view.php?id='.$id);exit;}catch(Throwable $e){$error=$e instanceof PDOException?'Could not save. Check for duplicate roll number/email.':$e->getMessage();}}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student form</title><link rel="stylesheet" href="style.css"></head><body><main class="narrow"><a href="index.php">← Back to list</a><h1><?=$id?'Edit':'Add'?> Student</h1><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="id" value="<?=$id?>"><label>Full name<input name="name" required value="<?=h($student['name'])?>"></label><label>Roll number<input name="roll_number" required value="<?=h($student['roll_number'])?>"></label><label>Email<input name="email" type="email" required value="<?=h($student['email'])?>"></label><label>Course<input name="course" required value="<?=h($student['course'])?>"></label><label>Documents (PDF/JPG/PNG, max 5 MB each)<input type="file" name="files[]" multiple accept=".pdf,.jpg,.jpeg,.png"></label><button>Save student</button></form></main></body></html>
